// Assets Fullbody Antonio Giancani (Fondatore & Immobiliare Giancani)
// Bundle ottimizzato con 4 pose anatomiche e 7 palette sartoriali intercambiabili ad ogni diretta
(function() {
  window.ANTONIO_SUIT_PALETTES = {
    'navy': { id: 'navy', name: 'Blu Notte Sartoriale', hex: '#1a2a44' },
    'antracite': { id: 'antracite', name: 'Grigio Antracite Tweed', hex: '#374151' },
    'bordeaux': { id: 'bordeaux', name: 'Bordeaux Prestige Rubino', hex: '#5c1d24' },
    'smeraldo': { id: 'smeraldo', name: 'Verde Bosco Smeraldo', hex: '#143a2b' },
    'nero': { id: 'nero', name: 'Nero Smoking Gala', hex: '#111827' },
    'cammello': { id: 'cammello', name: 'Cammello Luxury Sand', hex: '#b48c64' },
    'blureale': { id: 'blureale', name: 'Blu Reale Capri', hex: '#1d4ed8' },
  };

  // Base64 WebP Assets per palette e pose
  window.ASSETS_ANTONIO_PALETTES = {
    'navy': {
      'standing': 'data:image/webp;base64,',
      'walking': 'data:image/webp;base64,',
      'arms_raised': 'data:image/webp;base64,',
      'gesturing': 'data:image/webp;base64,',
    },
    'antracite': {
      'standing': 'data:image/webp;base64,',
      'walking': 'data:image/webp;base64,',
      'arms_raised': 'data:image/webp;base64,',
      'gesturing': 'data:image/webp;base64,',
    },
    'bordeaux': {
      'standing': 'data:image/webp;base64,',
      'walking': 'data:image/webp;base64,',
      'arms_raised': 'data:image/webp;base64,',
      'gesturing': 'data:image/webp;base64,',
    },
    'smeraldo': {
      'standing': 'data:image/webp;base64,',
      'walking': 'data:image/webp;base64,',
      'arms_raised': 'data:image/webp;base64,',
      'gesturing': 'data:image/webp;base64,',
    },
    'nero': {
      'standing': 'data:image/webp;base64,',
      'walking': 'data:image/webp;base64,',
      'arms_raised': 'data:image/webp;base64,',
      'gesturing': 'data:image/webp;base64,',
    },
    'cammello': {
      'standing': 'data:image/webp;base64,',
      'walking': 'data:image/webp;base64,',
      'arms_raised': 'data:image/webp;base64,',
      'gesturing': 'data:image/webp;base64,',
    },
    'blureale': {
      'standing': 'data:image/webp;base64,',
      'walking': 'data:image/webp;base64,',
      'arms_raised': 'data:image/webp;base64,',
      'gesturing': 'data:image/webp;base64,',
    },
  };

  // Default compatibilità retroattiva (navy)
  window.ASSETS_ANTONIO_FULLBODY = window.ASSETS_ANTONIO_PALETTES['navy'];

  // Funzione helper per ottenere l'asset corretto per palette e posa
  window.getAssetAntonioGiancani = function(posa, coloreAbito) {
    var p = posa || 'standing';
    var c = coloreAbito || window._coloreAbitoAttivoAntonio || 'navy';
    if (window.ASSETS_ANTONIO_PALETTES && window.ASSETS_ANTONIO_PALETTES[c] && window.ASSETS_ANTONIO_PALETTES[c][p]) {
      return window.ASSETS_ANTONIO_PALETTES[c][p];
    }
    // Fallback file path
    return 'assets/antonio_' + p + '_' + c + '.webp';
  };

  // Calcolo automatico colore abito per la diretta corrente (solo palette studio pulite ad alta fedeltà senza aloni su barba/scarpe)
  window.calcolaColoreAbitoDiretta = function(slotIndex) {
    var keys = ['navy', 'antracite', 'nero'];
    var now = new Date();
    var idx = (typeof slotIndex === 'number') ? slotIndex : (now.getDate() * 3 + now.getHours()) % keys.length;
    return keys[idx % keys.length];
  };

  console.log('👔 [ANTONIO-SUIT] Engine Palette Sartoriali caricato con successo (7 colori x 4 pose).');
})();
